#define MAX_A 200000

int main() {
    int N;
    scanf("%d", &N);

    int *freq = (int*)calloc(MAX_A + 1, sizeof(int));
    int *count_by_freq = (int*)calloc(N + 1, sizeof(int));

    for (int i = 0; i < N; i++) {
        int a;
        scanf("%d", &a);
        freq[a]++;
    }

    for (int i = 1; i <= MAX_A; i++) {
        if (freq[i] > 0) {
            count_by_freq[freq[i]]++;
        }
    }

    // total_cards_with_freq_at_least[x] = number of cards whose number appears at least x times
    int *total_cards_with_freq_at_least = (int*)calloc(N + 2, sizeof(int));
    for (int f = 1; f <= N; f++) {
        total_cards_with_freq_at_least[f] = total_cards_with_freq_at_least[f-1] + count_by_freq[f] * f;
    }

    // suffix sums of count_by_freq: number of distinct numbers with freq >= f
    int *distinct_with_freq_at_least = (int*)calloc(N + 2, sizeof(int));
    for (int f = N; f >= 1; f--) {
        distinct_with_freq_at_least[f] = distinct_with_freq_at_least[f+1] + count_by_freq[f];
    }

    for (int K = 1; K <= N; K++) {
        int lo = 0, hi = N / K;
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            // check if we can do 'mid' operations
            // Need mid * K distinct cards in each operation
            // Each number can be used at most freq[i] times
            long long need = (long long)mid * K;
            // We have at most sum over f of min(f, mid) * count_by_freq[f] cards available
            long long have = 0;
            // We can compute using prefix sums: 
            // for f <= mid: use f cards from each such number
            // for f > mid: use mid cards from each such number
            have += (long long) total_cards_with_freq_at_least[mid];
            have += (long long) distinct_with_freq_at_least[mid+1] * mid;
            if (have >= need) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        printf("%d\n", lo);
    }

    free(freq);
    free(count_by_freq);
    free(total_cards_with_freq_at_least);
    free(distinct_with_freq_at_least);

    return 0;
}

