    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *A = (long long *)malloc(sizeof(long long) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(long long), cmp_ll);

    // Count frequencies of distinct values
    int M = 0;
    int *freq = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; ) {
        int j = i + 1;
        while (j < N && A[j] == A[i]) j++;
        freq[M++] = j - i;
        i = j;
    }

    // cnt[t] = number of values appearing exactly t times
    int *cnt = (int *)calloc(N + 1, sizeof(int));
    for (int i = 0; i < M; i++) cnt[freq[i]]++;

    // g[x] = sum over values of min(freq, x)
    // We compute it incrementally:
    // g[x] = g[x-1] + number of values with freq >= x
    long long *g = (long long *)malloc(sizeof(long long) * (N + 1));
    g[0] = 0;

    int ge = M; // number of values with freq >= current x
    for (int x = 1; x <= N; x++) {
        g[x] = g[x - 1] + ge;
        ge -= cnt[x];
    }

    // For each K, answer is max x such that g[x] >= K*x
    // Since answers are non-increasing in K, use a decreasing pointer.
    int x = N;
    for (int K = 1; K <= N; K++) {
        while (x > 0 && g[x] < (long long)K * x) x--;
        printf("%d\n", x);
    }

    free(A);
    free(freq);
    free(cnt);
    free(g);
    return 0;
}

